Class Producto
  Define nombre As String;
  Define precio As Integer;

  Method Constructor(n As String, p As Integer)
    This.nombre <- n;
    This.precio <- p;
  EndMethod
EndClass

Class Inventario
  Private Define stock As Dictionary<String, Integer>;

  Method Constructor()
    This.stock <- dictionary();
  EndMethod

  Method Cargar(nombre As String, cantidad As Integer)
    This.stock[nombre] <- cantidad;
  EndMethod

  Method Quitar(nombre As String, cantidad As Integer) As Boolean
    If cantidad > This.stock[nombre] Then
      Return False;
    EndIf
    This.stock[nombre] <- This.stock[nombre] - cantidad;
    Return True;
  EndMethod
EndClass

Class Ticket
  Private Define lineas As Vector<String>;

  Method Constructor()
    This.lineas <- vector();
  EndMethod

  Method Anotar(linea As String)
    This.lineas.append(linea);
  EndMethod

  Method Imprimir()
    For Each linea In This.lineas Do
      Write linea;
    EndFor
  EndMethod
EndClass

Class Caja
  Private Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Vender(producto As Producto, cantidad As Integer, inventario As Inventario, ticket As Ticket)
    If inventario.Quitar(producto.nombre, cantidad) Then
      This.total <- This.total + producto.precio * cantidad;
      ticket.Anotar(producto.nombre + " x " + toText(cantidad) + " = " + toText(producto.precio * cantidad));
    Else
      ticket.Anotar(producto.nombre + " x " + toText(cantidad) + " rechazado");
    EndIf
  EndMethod

  Method Total() As Integer
    Return This.total;
  EndMethod
EndClass

Algorithm Kiosco
  Define jugos, sandwiches As Integer;
  Read jugos;
  Read sandwiches;
  Define jugo As Producto <- New Producto("Jugo", 3);
  Define sandwich As Producto <- New Producto("Sándwich", 5);
  Define inventario As Inventario <- New Inventario();
  inventario.Cargar("Jugo", 10);
  inventario.Cargar("Sándwich", 5);
  Define ticket As Ticket <- New Ticket();
  Define caja As Caja <- New Caja();
  caja.Vender(jugo, jugos, inventario, ticket);
  caja.Vender(sandwich, sandwiches, inventario, ticket);
  ticket.Imprimir();
  Write "Total: ", caja.Total();
EndAlgorithm

